insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('c770506f-8d95-d911-9ef7-7a6f87f97183','41f9aabd-60fc-4e1d-d299-bbcd73b523fe','cover',2,'needs_review','{"id":"c770506f-8d95-d911-9ef7-7a6f87f97183","activity_id":"41f9aabd-60fc-4e1d-d299-bbcd73b523fe","lesson_id":"AF01","domain_id":"D01","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"AF01 · What Is Artificial Intelligence? · cover","caption":"Identify the lesson and its central decision at a glance. Distinguish learned prediction from fixed rules and human judgment.","alt_text":"A capacity gate, pattern-sorting tray and a person considering a card represent fixed rules, learned patterns and human judgment.","extended_description":"Distinguish learned prediction from fixed rules and human judgment.\n\nA campus room booking limit can be enforced by a fixed capacity rule. Classifying free-text maintenance requests may benefit from a trained model, but uncertain cases still need a person. Choose the rule for capacity because its decision criterion is explicit.\n\nAutomation may follow fixed rules. Select a method from the task, evidence and cost of error.","format":"webp","asset_path":"curriculum/assets/visuals/AF/AF01/cover/generated/AF01-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/AF/AF01/cover/generated/AF01-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. Asset: BTG AI AF01 ''What Is Artificial Intelligence?'' lesson cover, one finished 16:9 editorial illustration, high-resolution. Canonical objective: distinguish learned prediction from fixed rules and human judgment. Canonical example: a campus room capacity is governed by a fixed rule; free-text maintenance classification can use a learned model; uncertain cases need a person. Create a restrained, premium editorial scene with one dominant three-way decision instrument: a tactile ruled gate, a small patterned sorting surface, and a human hand considering a card, all part of one coherent central tabletop composition. Secondary context: a subtle contemporary university notice card, no writing. Abstract modern educational illustration, flat shapes with subtle paper texture and modest depth, precise elegant edges, dark indigo background #141724, muted violet and cyan accents, warm natural hand tone. Keep all essential subject matter inside central 45% width for 4:5 and 1:1 crops, generous empty margins and upper title-safe space. No text, numbers, logos, fake UI, arrows, diagram boxes, robots, brains, holograms, neon, stock imagery or invented outcomes. This is lesson identity artwork, not a concept diagram or assessment solution.","generation_model":null,"provenance":{"source_refs":["AF01.instruction","AF01.worked-example","AF01.practice.v1","curriculum/assets/visuals/AF/AF01/cover/source/AF01-cover-master-v1.png"],"source_hash":"710218830d7f812e0b33e576f59d81639d5e216af3b32f6a1e37088d73b9fcac","renderer_version":"btg-visuals-1","asset_hash":"0083ad43fe69837e885d54ac146bc534b59d77caaef3de0774cf5042f8936c16"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/AF/AF01/cover/generated/AF01-cover-portrait-v2.webp","curriculum/assets/visuals/AF/AF01/cover/generated/AF01-cover-square-v2.webp","curriculum/assets/visuals/AF/AF01/cover/generated/AF01-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
update public.curriculum_visual_assets set status='rejected',review_reason='Replaced: a concept panel does not satisfy the editorial cover contract.' where activity_id='40e5b67b-5a6c-f1ed-5118-a2e1086cc7b2' and visual_type='cover' and version=1 and status='needs_review';
insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('4abd966f-2682-21c1-a84f-ba74c5a2ffcd','40e5b67b-5a6c-f1ed-5118-a2e1086cc7b2','cover',2,'needs_review','{"id":"4abd966f-2682-21c1-a84f-ba74c5a2ffcd","activity_id":"40e5b67b-5a6c-f1ed-5118-a2e1086cc7b2","lesson_id":"PC07","domain_id":"D03","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"PC07 · Context Engineering · cover","caption":"Identify the lesson and its central decision at a glance. Select and organize the minimum authorized context needed for a task.","alt_text":"A selection aperture isolates two relevant source pages while unrelated material stays outside the context boundary.","extended_description":"Select and organize the minimum authorized context needed for a task.\n\nA tutor explaining an objective needs approved lesson content and the learner attempt, but not another student submission or a hidden answer key. Filter before constructing the request.\n\nPermission and relevance determine what enters context. More data does not create authority.","format":"webp","asset_path":"curriculum/assets/visuals/PC/PC07/cover/generated/PC07-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/PC/PC07/cover/generated/PC07-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI lesson identity cover, 16:9 high-resolution editorial illustration. Premium contemporary academic illustration, dark indigo #141724, restrained violet and cyan, subtle paper texture, flat forms with modest depth. One dominant metaphor and one secondary contextual element. No text, numbers, logos, diagram boxes, arrows, fake dashboards, brains, robots, neon or stock imagery. Keep essential subject inside central 40% width and central 65% height, generous title-safe negative space, safe center crops to 4:5 and 1:1. This is cover art, not an explanatory diagram. Lesson: Context Engineering. Objective: select and organize minimum authorized context. Canonical example: tutor needs approved lesson and learner''s own attempt, not other learners'' work or a hidden answer key. Dominant metaphor: a precision translucent selection aperture gathering just two relevant unmarked paper fragments into a neat focused bundle; other fragments remain outside the aperture. Secondary element: a quiet layered reference sheet. Show information selection and boundary, not a padlock. No assessment answers.","generation_model":null,"provenance":{"source_refs":["PC07.instruction","PC07.worked-example","PC07.practice.v1","curriculum/assets/visuals/PC/PC07/cover/source/PC07-cover-master-v1.png"],"source_hash":"0c26597724a5f0c90430aaf92bf5f78c193cb3c6e047a776af14a33aaa379976","renderer_version":"btg-visuals-1","asset_hash":"1bb9475dc96e9520c2504907f05b8d68b5add65f13f1d7377c2500c7a5be494e"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/PC/PC07/cover/generated/PC07-cover-portrait-v2.webp","curriculum/assets/visuals/PC/PC07/cover/generated/PC07-cover-square-v2.webp","curriculum/assets/visuals/PC/PC07/cover/generated/PC07-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
update public.curriculum_visual_assets set status='rejected',review_reason='Replaced: a concept panel does not satisfy the editorial cover contract.' where activity_id='3559736a-3804-5163-9951-9adb33d8fe44' and visual_type='cover' and version=1 and status='needs_review';
insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('4d06e1cc-b2fa-884f-cbb8-c2b397473898','3559736a-3804-5163-9951-9adb33d8fe44','cover',2,'needs_review','{"id":"4d06e1cc-b2fa-884f-cbb8-c2b397473898","activity_id":"3559736a-3804-5163-9951-9adb33d8fe44","lesson_id":"AA07","domain_id":"D04","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"AA07 · Human Approval & Guardrails · cover","caption":"Identify the lesson and its central decision at a glance. Place approval before consequential side effects and recheck its scope.","alt_text":"A person holds an approval gate around a narrow proposal while a wider changed proposal waits outside its scope.","extended_description":"Place approval before consequential side effects and recheck its scope.\n\nAn organizer approves a message for 20 recipients. If the agent changes the recipient list to 200, the old approval is insufficient. Bind approval to the reviewed proposal and require another decision.\n\nA materially changed proposal needs fresh approval before any consequential side effect.","format":"webp","asset_path":"curriculum/assets/visuals/AA/AA07/cover/generated/AA07-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/AA/AA07/cover/generated/AA07-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI lesson identity cover, 16:9 high-resolution editorial illustration. Premium contemporary academic illustration, dark indigo #141724, restrained violet and cyan, subtle paper texture, flat forms with modest depth. One dominant metaphor and one secondary contextual element. No text, numbers, logos, diagram boxes, arrows, fake dashboards, brains, robots, neon or stock imagery. Keep essential subject inside central 40% width and central 65% height, generous title-safe negative space, safe center crops to 4:5 and 1:1. This is cover art, not an explanatory diagram. Lesson: Human Approval & Guardrails. Objective: bind approval to exact proposal and recheck scope before side effects. Canonical example: changing a message''s recipients from 20 to 200 invalidates prior approval. Dominant metaphor: an adjustable aperture gate held by a human hand at a paused decision point; a narrow paper ribbon fits its approved opening while a visibly wider folded ribbon waits beside it. Secondary element: a blank approval seal lying unused. No checkmark suggesting the wider proposal is approved. Natural dark skin hand, contemporary university technology context, no ethnic motifs.","generation_model":null,"provenance":{"source_refs":["AA07.instruction","AA07.worked-example","AA07.practice.v1","curriculum/assets/visuals/AA/AA07/cover/source/AA07-cover-master-v1.png"],"source_hash":"9f6bc756f35df40e59db06f5fbdf99d9c3ac68cb8badb752c68ae87a296e4eb6","renderer_version":"btg-visuals-1","asset_hash":"d12cd6156c27458aeec1a4b304d5b6475f364a0eb1bdb76539300aa9c56dc48d"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/AA/AA07/cover/generated/AA07-cover-portrait-v2.webp","curriculum/assets/visuals/AA/AA07/cover/generated/AA07-cover-square-v2.webp","curriculum/assets/visuals/AA/AA07/cover/generated/AA07-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
update public.curriculum_visual_assets set status='rejected',review_reason='Replaced: a concept panel does not satisfy the editorial cover contract.' where activity_id='b3fb6239-caf2-e269-d09f-6d0674baa3cd' and visual_type='cover' and version=1 and status='needs_review';
insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('7622a008-7ae6-1285-9567-3fd17bac0f19','b3fb6239-caf2-e269-d09f-6d0674baa3cd','cover',2,'needs_review','{"id":"7622a008-7ae6-1285-9567-3fd17bac0f19","activity_id":"b3fb6239-caf2-e269-d09f-6d0674baa3cd","lesson_id":"SE10","domain_id":"D05","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"SE10 · Databases · cover","caption":"Identify the lesson and its central decision at a glance. Model relationships and enforce invariants in persistent storage.","alt_text":"Learner and course tabs fit together in one record drawer, representing related data protected by a unique enrollment constraint.","extended_description":"Model relationships and enforce invariants in persistent storage.\n\nAn enrollment table references learner and course IDs and has a unique learner/course pair. Two concurrent enrollment requests then cannot create duplicate enrollment records even if both passed an earlier UI check.\n\nEnforce uniqueness in the database; two requests can both pass an earlier UI check.","format":"webp","asset_path":"curriculum/assets/visuals/SE/SE10/cover/generated/SE10-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/SE/SE10/cover/generated/SE10-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI educational lesson cover, high-resolution 16:9. One dominant editorial visual metaphor, one subtle secondary context element, no explanatory diagram. Sophisticated matte cut-paper illustration, indigo #141724 background, restrained cyan and violet, quiet warm neutrals, tactile paper, soft subtle depth. Essential subject grouped within the central 40% of the frame for square and 4:5 crops, generous empty border and title-safe upper margin. No text, letters, numerals, chart values, logos, robots, brains, neon or fictitious dashboards. Lesson Databases: model relationships and enforce invariants in persistent storage. Canonical example: learner/course enrollment references both IDs and enforces a unique pair against concurrent duplicate requests. Dominant metaphor: two keyed filing tabs joined into a single precisely fitted record drawer, while a duplicate tab rests outside the slot. Secondary element: two small blank index cards representing learner and course. The central tangible join and one-slot constraint should identify relational data. Not a database architecture diagram.","generation_model":null,"provenance":{"source_refs":["SE10.instruction","SE10.worked-example","SE10.practice.v1","curriculum/assets/visuals/SE/SE10/cover/source/SE10-cover-master-v1.png"],"source_hash":"290c122cc2fcf87ca816ca2c227a7e910c8f91db1fc0020f13e9d0c5f561f43a","renderer_version":"btg-visuals-1","asset_hash":"2901015a4188655e594c1a515fcd4a3964eb14c3a444a3012d1711dd333aba31"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/SE/SE10/cover/generated/SE10-cover-portrait-v2.webp","curriculum/assets/visuals/SE/SE10/cover/generated/SE10-cover-square-v2.webp","curriculum/assets/visuals/SE/SE10/cover/generated/SE10-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
update public.curriculum_visual_assets set status='rejected',review_reason='Replaced: a concept panel does not satisfy the editorial cover contract.' where activity_id='92e3a477-bef5-05fe-5c7c-1899b6359655' and visual_type='cover' and version=1 and status='needs_review';
insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('9943109d-791c-9c4a-3fd1-4415abe18a06','92e3a477-bef5-05fe-5c7c-1899b6359655','cover',2,'needs_review','{"id":"9943109d-791c-9c4a-3fd1-4415abe18a06","activity_id":"92e3a477-bef5-05fe-5c7c-1899b6359655","lesson_id":"DA08","domain_id":"D06","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"DA08 · Data Visualization · cover","caption":"Identify the lesson and its central decision at a glance. Choose a chart that supports a specific comparison honestly.","alt_text":"A straightedge aligns two symbolic columns to a shared baseline, emphasizing honest comparison rather than exaggerated differences.","extended_description":"Choose a chart that supports a specific comparison honestly.\n\nA bar chart starting its axis near the smallest value exaggerates a small completion-rate difference. Use an appropriate baseline and show the rates and cohort sizes explicitly.\n\nDramatic appearance is not accuracy. Explain the baseline and retain rates, cohort sizes and uncertainty.","format":"webp","asset_path":"curriculum/assets/visuals/DA/DA08/cover/generated/DA08-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/DA/DA08/cover/generated/DA08-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI educational lesson cover, high-resolution 16:9. One dominant editorial visual metaphor, one subtle secondary context element, no explanatory diagram. Sophisticated matte cut-paper illustration, indigo #141724 background, restrained cyan and violet, quiet warm neutrals, tactile paper, soft subtle depth. Essential subject grouped within the central 40% of the frame for square and 4:5 crops, generous empty border and title-safe upper margin. No text, letters, numerals, chart values, logos, robots, brains, neon or fictitious dashboards. Lesson Data Visualization: choose honest visual comparison. Canonical example: truncated bar-chart baseline can exaggerate a small completion-rate difference; preserve appropriate baseline, rate labels and cohort sizes in real analysis. Dominant metaphor: a drafting straightedge leveling the base of two abstract paper columns, with an offset loose baseline strip beside it. Secondary element: a blank data sheet. This is a symbolic editorial motif, not an actual data chart: no ticks, quantities, axes labels or implied measured outcomes. Emphasize fair comparison and scale.","generation_model":null,"provenance":{"source_refs":["DA08.instruction","DA08.worked-example","DA08.practice.v1","curriculum/assets/visuals/DA/DA08/cover/source/DA08-cover-master-v1.png"],"source_hash":"d30cb998c9c5fe87770f1f0a1b24bfcfddf85704575aa94e819a360b0eff9a39","renderer_version":"btg-visuals-1","asset_hash":"9c3c6a7dca1b95fda580b11e2e2c6de2e3b5cf6881fb72cf4f741fd6c744f768"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/DA/DA08/cover/generated/DA08-cover-portrait-v2.webp","curriculum/assets/visuals/DA/DA08/cover/generated/DA08-cover-square-v2.webp","curriculum/assets/visuals/DA/DA08/cover/generated/DA08-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
update public.curriculum_visual_assets set status='rejected',review_reason='Replaced: a concept panel does not satisfy the editorial cover contract.' where activity_id='fa75fa6f-224d-64b7-d82c-14ce8f2542cf' and visual_type='cover' and version=1 and status='needs_review';
insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('c4438b32-1a21-cb00-08c7-ecf2d984878d','fa75fa6f-224d-64b7-d82c-14ce8f2542cf','cover',2,'needs_review','{"id":"c4438b32-1a21-cb00-08c7-ecf2d984878d","activity_id":"fa75fa6f-224d-64b7-d82c-14ce8f2542cf","lesson_id":"CS03","domain_id":"D08","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"CS03 · Authorization & Least Privilege · cover","caption":"Identify the lesson and its central decision at a glance. Enforce ownership and role permissions on every protected operation.","alt_text":"Distinct identity tabs match only their own document sleeves, representing record ownership rather than blanket access.","extended_description":"Enforce ownership and role permissions on every protected operation.\n\nTwo learners can each edit their own tasks. Changing a task ID in a request must not let one edit the other task, even though both are authenticated learners.\n\nBeing authenticated does not authorize access to another learner’s record.","format":"webp","asset_path":"curriculum/assets/visuals/CS/CS03/cover/generated/CS03-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/CS/CS03/cover/generated/CS03-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI lesson cover, one high-resolution 16:9 editorial illustration. Restrained premium academic matte paper illustration, dark indigo #141724, violet and cyan accents, soft depth, strong focal subject, ample negative space for semantic UI title outside artwork. Central subject must fit inside central 40% width and 65% height, safe for 4:5 and square center crops. One metaphor and one contextual detail, no infographic. No text, letters, numbers, logos, arrows, diagram boxes, robots, brains, hooded hackers, neon or fake UI. Lesson Authorization & Least Privilege. Objective: enforce ownership and role permissions on every protected operation. Canonical example: authenticated learner A can edit their own task but cannot edit learner B''s task by changing its ID. Metaphor: two neighboring personal document sleeves with distinct geometric identity tabs; a single matching shaped access token aligns only with its own sleeve and visibly does not fit the other. Secondary element: a quiet boundary divider between sleeves. Do not use a padlock. Focus on scoped fit and ownership, not security theater.","generation_model":null,"provenance":{"source_refs":["CS03.instruction","CS03.worked-example","CS03.practice.v1","curriculum/assets/visuals/CS/CS03/cover/source/CS03-cover-master-v1.png"],"source_hash":"d02d4405a68fd5914b2fed71c166170b88c977c73caac11bdaa4dfd6d0b28427","renderer_version":"btg-visuals-1","asset_hash":"d4756e16eebe0b5f67193e37508c5876570748e64d670c90fe49362fa3ace721"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/CS/CS03/cover/generated/CS03-cover-portrait-v2.webp","curriculum/assets/visuals/CS/CS03/cover/generated/CS03-cover-square-v2.webp","curriculum/assets/visuals/CS/CS03/cover/generated/CS03-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
update public.curriculum_visual_assets set status='rejected',review_reason='Replaced: a concept panel does not satisfy the editorial cover contract.' where activity_id='cfac1136-32a0-fc11-463b-d65f8b551191' and visual_type='cover' and version=1 and status='needs_review';
insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('57808753-1a33-7853-a005-afa5c6a5d37c','cfac1136-32a0-fc11-463b-d65f8b551191','cover',2,'needs_review','{"id":"57808753-1a33-7853-a005-afa5c6a5d37c","activity_id":"cfac1136-32a0-fc11-463b-d65f8b551191","lesson_id":"EI06","domain_id":"D10","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"EI06 · Building an MVP · cover","caption":"Identify the lesson and its central decision at a glance. Choose the smallest experiment that tests a consequential assumption.","alt_text":"A learner tests a small manual room-booking board before investing in automation, with an observation notebook nearby.","extended_description":"Choose the smallest experiment that tests a consequential assumption.\n\nBefore building automated room matching, manually coordinate a small authorized group using a shared schedule. Measure successful bookings and effort to learn whether coordination solves the problem.\n\nAn MVP tests a consequential assumption; it need not automate the whole product.","format":"webp","asset_path":"curriculum/assets/visuals/EI/EI06/cover/generated/EI06-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/EI/EI06/cover/generated/EI06-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI lesson cover, one high-resolution 16:9 editorial illustration. Restrained premium academic matte paper illustration, dark indigo #141724, violet and cyan accents, soft depth, strong focal subject, ample negative space for semantic UI title outside artwork. Central subject must fit inside central 40% width and 65% height, safe for 4:5 and square center crops. One metaphor and one contextual detail, no infographic. No text, letters, numbers, logos, arrows, diagram boxes, robots, brains, hooded hackers, neon or fake UI. Lesson Building an MVP. Objective: smallest experiment testing a consequential assumption. Canonical example: manually coordinate a small authorized group''s room bookings using a shared schedule before building automated matching; measure bookings and effort. Metaphor: a small handmade room-booking prototype assembled from a few movable paper schedule tabs, with a human hand testing one piece. Secondary element: an unmarked observation notebook. Natural African university learner hand, modern workspace. Show bounded experimentation, not launch celebration, rocket or guaranteed growth.","generation_model":null,"provenance":{"source_refs":["EI06.instruction","EI06.worked-example","EI06.practice.v1","curriculum/assets/visuals/EI/EI06/cover/source/EI06-cover-master-v1.png"],"source_hash":"b87a75ef246a7a3234481a4b27fc28a26a7082d4fc82d55dd60dc987912f2fe2","renderer_version":"btg-visuals-1","asset_hash":"1bb7770ebe857d132b6911901e11348461bc2626c1afa7a765bf3c71bc1296fc"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/EI/EI06/cover/generated/EI06-cover-portrait-v2.webp","curriculum/assets/visuals/EI/EI06/cover/generated/EI06-cover-square-v2.webp","curriculum/assets/visuals/EI/EI06/cover/generated/EI06-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
