insert into public.curriculum_visual_assets(id,activity_id,visual_type,version,status,metadata) values ('c18d8148-9a40-70c6-b74b-4308ded50b52','33c73104-412d-763c-027e-6c7f56a43428','cover',2,'needs_review','{"id":"c18d8148-9a40-70c6-b74b-4308ded50b52","activity_id":"33c73104-412d-763c-027e-6c7f56a43428","lesson_id":"VC10","domain_id":"D11","curriculum_version_id":1,"visual_type":"cover","learning_purpose":"Identify the lesson and its central decision at a glance.","title":"VC10 · Testing & E2E Verification · cover","caption":"Identify the lesson and its central decision at a glance. Verify the user journey and negative cases against real persisted behavior.","alt_text":"A persistent record remains inside a refresh ring while a separate access boundary represents testing another user’s permissions.","extended_description":"Verify the user journey and negative cases against real persisted behavior.\n\nA browser test creates a task and sees it in memory, but never reloads. Add a reload and verify the saved task through the real backend, then test that a second user cannot edit it. Record skipped tests as unverified.\n\nA mocked or memory-only pass is not production evidence. Skipped checks remain unverified.","format":"webp","asset_path":"curriculum/assets/visuals/VC/VC10/cover/generated/VC10-cover-v2.webp","thumbnail_path":"curriculum/assets/visuals/VC/VC10/cover/generated/VC10-cover-thumbnail-v2.webp","width":1600,"height":900,"aspect_ratio":"1600:900","source_type":"image_generation","generation_prompt":"Use case: stylized-concept. BTG AI VC10 Testing & E2E Verification lesson identity cover. Canonical objective: verify user journeys and negative cases against real persisted behavior. Canonical example: creating a task visible in browser memory is insufficient; reload through real backend and verify a second user cannot edit it, recording skipped checks as unverified. Create one premium editorial matte-paper illustration, 16:9 wide. Dominant metaphor: a solid physical record block visibly retained behind a translucent refresh ring; a separate mismatched access tab rests at a boundary nearby. Secondary context: a small folded test checklist with blank lines, no checkmarks implying tests ran. Center the whole symbolic arrangement in middle 40% width with large indigo #141724 margins for portrait/square crops and title-safe space above. Cyan and lavender edge accents, subtle paper texture and soft depth. No laptop, terminal text, code, arrows, architecture boxes, numbers, letters, logos, robot, glowing brain, neon or futuristic dashboard. This is abstract cover artwork about persistence and independent verification, not a diagram or evidence of real executed tests.","generation_model":null,"provenance":{"source_refs":["VC10.instruction","VC10.worked-example","VC10.practice.v1","curriculum/assets/visuals/VC/VC10/cover/source/VC10-cover-master-v1.png"],"source_hash":"8f15786ecfcca5457856ec89ceafa0e669b71d5c0d3350200f9eb94f3ab3a64e","renderer_version":"btg-visuals-1","asset_hash":"2cd4294810fa3516311575277178e4c9e681f808535ce8c7527eb1a8c3a232af"},"status":"needs_review","version":2,"created_at":"2026-09-20T00:00:00.000Z","reviewed_at":null,"reviewed_by":null,"published_at":null,"review_reason":null,"generation_provider":"builtin_image_gen","responsive_variants":["curriculum/assets/visuals/VC/VC10/cover/generated/VC10-cover-portrait-v2.webp","curriculum/assets/visuals/VC/VC10/cover/generated/VC10-cover-square-v2.webp","curriculum/assets/visuals/VC/VC10/cover/generated/VC10-cover-small-v2.webp"]}'::jsonb) on conflict(activity_id,visual_type,version) do nothing;
